import numpy as np
from scipy.optimize import least_squares
m=meas['m1']; x=m['two_theta']; y=m['counts']
def pv(x,c,fwhm,eta=0.5):
    g=np.exp(-4*np.log(2)*((x-c)/fwhm)**2)
    l=1/(1+4*((x-c)/fwhm)**2)
    return eta*l+(1-eta)*g
def model(p,ndoub):
    if ndoub==1:
        c,f,A,b0,b1=p
        return A*pv(x,c,f)+b0+b1*(x-45)
    else:
        c,d,f,A1,r,b0,b1=p
        return A1*(pv(x,c,f)+r*pv(x,c+d,f))+b0+b1*(x-45)
def res(p,nd):
    m_=model(p,nd); return (y-m_)/np.sqrt(np.maximum(m_,1))
r1=least_squares(res,[45.26,0.2,100,85,0],args=(1,))
