best=None
for d0 in [0.05,0.1,0.15,0.2]:
    r2=least_squares(res,[45.2,d0,0.12,100,0.5,85,0],args=(2,),bounds=([44.9,0,0.02,0,0,0,-100],[45.6,0.5,0.4,1000,3,300,100]))
    c2=np.sum(res(r2.x,2)**2)
    if best is None or c2<best[1]: best=(r2.x,c2)
print('doublet',best[0],best[1])
# also fixed-separation scan
for d in np.arange(0,0.25,0.02):
    rr=least_squares(lambda p: res([p[0],d,p[1],p[2],p[3],p[4],p[5]],2),[45.2,0.12,100,0.5,85,0],bounds=([44.9,0.02,0,0,0,-100],[45.6,0.4,1000,3,300,100]))
    print(round(d,3), round(np.sum(rr.fun**2),2), np.round(rr.x[:2],3))

